<script setup lang="ts">
import {computed} from 'vue'
import {IconHeart,IconLock,IconCircleOff,IconAlertCircle,IconChevronRight,IconSparkles} from '@tabler/icons-vue'
import type {ProfileDocument,ProfileSection} from './profile-api'
import {referenceName,type Catalogue} from './profile-fields'
const props=defineProps<{document:ProfileDocument;catalogue:Catalogue;ru:boolean}>()
const emit=defineEmits<{edit:[ProfileSection]}>()
const liked=computed(()=>props.document.preferences?.practices?.filter(p=>p.attitude==='like'||p.attitude==='want_to_try')??[])
const limits=computed(()=>props.document.preferences?.practices?.filter(p=>p.attitude==='taboo'||p.attitude==='conditional')??[])
</script>
<template><div class="profile-overview-columns"><section><header><h3>{{ru?'Что мне нравится':'What I like'}}</h3><button class="quiet-button" @click="emit('edit','preferences')"><IconChevronRight :size="20"/><span class="sr-only">{{ru?'Редактировать предпочтения':'Edit preferences'}}</span></button></header><p class="muted">{{ru?'Близкие мне темы и то, что хочется исследовать.':'Things I enjoy and would like to explore.'}}</p><button v-for="item in liked.slice(0,5)" :key="item.practice_uid" class="profile-overview-row" @click="emit('edit','preferences')"><IconHeart v-if="item.attitude==='like'" :size="25"/><IconSparkles v-else :size="25"/><span><strong>{{referenceName(catalogue,item.practice_uid)}}</strong><small>{{item.attitude==='like'?(ru?'Нравится':'Like'):(ru?'Хочу попробовать':'Want to try')}}</small></span><IconChevronRight :size="18"/></button><p v-if="!liked.length" class="profile-empty">{{ru?'Здесь появятся ваши предпочтения. Можно начать с одной практики.':'Your preferences will appear here. Start with a single practice.'}}</p></section><section><header><h3>{{ru?'Мои границы':'My boundaries'}}</h3><button class="quiet-button" @click="emit('edit','boundaries')"><IconChevronRight :size="20"/><span class="sr-only">{{ru?'Редактировать границы':'Edit boundaries'}}</span></button></header><p class="muted">{{ru?'То, что важно учитывать во взаимодействии.':'What matters when interacting with me.'}}</p><button v-for="item in limits.slice(0,5)" :key="item.practice_uid" class="profile-overview-row" @click="emit('edit','preferences')"><IconCircleOff v-if="item.attitude==='taboo'" class="profile-taboo" :size="25"/><IconAlertCircle v-else :size="25"/><span><strong>{{referenceName(catalogue,item.practice_uid)}}</strong><small>{{item.attitude==='taboo'?(ru?'Табу':'Taboo'):(ru?'При условиях':'Conditional')}}<template v-if="item.conditions"> · {{item.conditions}}</template></small></span><IconChevronRight :size="18"/></button><p v-if="!limits.length" class="profile-empty">{{ru?'Границы пока не указаны. Пустой ответ не означает разрешения.':'Boundaries are not specified. An empty answer is not permission.'}}</p><p v-if="document.boundaries?.notes" class="profile-personal-note">{{document.boundaries.notes}}</p></section></div><button class="profile-health-row" @click="emit('edit','health')"><IconLock :size="24"/><span><strong>{{ru?'Здоровье и забота':'Health & care'}}</strong><small>{{ru?'Личный раздел · доступ настраивается отдельно':'Personal section · visibility managed separately'}}</small></span><IconChevronRight :size="20"/></button></template>
